#!/usr/bin/env python3
"""Build the dependency-free root index from the published audit ledger."""
from pathlib import Path
from html import escape as e
import json

here=Path(__file__).resolve().parent
root=here.parents[1]
data=json.loads((here/'results.json').read_text())
base='https://github.com/enuminous/Jacobian/blob/main/audits/2026-11-05/'
cards=[]
for r in data['animals']:
    search=e((r['name']+' '+r['operation']+' '+r['status']).lower(),quote=True)
    cards.append(f'''<details class="animal" data-status="{r['status']}" data-search="{search}">
      <summary><span class="number">{r['entry']:02d}</span><span class="animal-name">{e(r['name'])}</span><span class="tag {r['status'].lower()}">{r['status']}</span></summary>
      <div class="animal-body"><p class="operation">{e(r['operation'])}</p>
      <dl><dt>Inputs</dt><dd>{e(r['inputs'])}</dd><dt>Transformation</dt><dd>{e(r['transformation'])}</dd><dt>Criterion</dt><dd>{e(r['criterion'])}</dd><dt>Observed output</dt><dd>{e(r['output'])}</dd></dl>
      <p class="small">{e(r['execution'])} · <a href="{e(r['source_url'],quote=True)}">Source operation</a> · <a href="{base+e(r['evidence'],quote=True)}">Evidence</a></p></div></details>''')
